void ControlBar::populateInvDataCallback(Object *obj, void *userData)
{
	PopulateInvButtonData *data = (PopulateInvButtonData *)userData;

	// if we're beyond the max the GUI can support, bail out
	if (data->currIndex > data->maxIndex)
		return;

	const Image *image = getButtonImage((ThingTemplate *)obj->getTemplate(), obj);

	int transportCount = obj->getTransportSlotCount();
	int i = 0;
	if (transportCount <= 0)
		return;
	do
	{
		// assign our control and object id to the transport data
		GameWindow *control = data->controls[data->currIndex];
		ControlBarInventoryEntries[data->currIndex].control = control;
		ControlBarInventoryEntries[data->currIndex].objectID = obj->getID();
		data->currIndex++;

		GadgetButtonSetEnabledImage_Rva002C0433(control, image);
		Rva003284ED(control, 0);

		if (i == 0)
		{
			control->winEnable(true);
			control->winSetStatus(8);
			control->winClearStatus(0x200);
		}
		else
		{
			control->winEnable(false);
			control->winClearStatus(8);
			control->winSetStatus(0x200);
		}
		i++;
	} while (i < transportCount);
}

